inline bool detect_texture_packer(flight::String text) {
  if ((text.trim_start().char_at(0.0) != flight::String("{"))) {
    return false;
  }
  return (flight::RegExp(flight::String("\"meta\"\\s*:"), flight::String("")).test(text) && flight::RegExp(flight::String("\"app\"\\s*:"), flight::String("")).test(text));
}

inline bool detect_aseprite(flight::String text) {
  if ((text.trim_start().char_at(0.0) != flight::String("{"))) {
    return false;
  }
  return (flight::RegExp(flight::String("\"meta\"\\s*:"), flight::String("")).test(text) && flight::RegExp(flight::String("aseprite\\.org"), flight::String("i")).test(text));
}

inline bool detect_cocos_plist(flight::String text) {
  const flight::String trimmed = text.trim_start();
  return (((trimmed.char_at(0.0) == flight::String("<")) || trimmed.starts_with(flight::String("<?xml"))) && flight::RegExp(flight::String("<plist\\b"), flight::String("i")).test(text));
}

inline bool detect_starling(flight::String text) {
  return flight::RegExp(flight::String("<TextureAtlas\\b"), flight::String("i")).test(text);
}

inline bool detect_libgdx_atlas(flight::String text) {
  const flight::String ch = text.trim_start().char_at(0.0);
  if (((ch == flight::String("<")) || (ch == flight::String("{")))) {
    return false;
  }
  return (flight::RegExp(flight::String("^\\s*rotate\\s*:"), flight::String("m")).test(text) || flight::RegExp(flight::String("^\\s*xy\\s*:"), flight::String("m")).test(text));
}

